function getNodeItems(name) {
  try {
    return $(name).all();
  } catch (error) {
    try {
      return $items(name);
    } catch (fallbackError) {
      return [];
    }
  }
}

function normalizeWebsite(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  return /^https?:\/\//i.test(raw) ? raw.replace(/\/$/, '') : 'https://' + raw.replace(/\/$/, '');
}

const providerItems = $input.all();
if (!providerItems.length) {
  throw new Error('No VPN providers were returned from the provider sheet.');
}

const domainItems = getNodeItems('Define Portfolio Domains & Personas');
if (!domainItems.length) {
  throw new Error('No portfolio domain items are available from Define Portfolio Domains & Personas.');
}

const aggregateItems = getNodeItems('Aggregate');
const keywords = Array.isArray(aggregateItems[0]?.json?.keywords) ? aggregateItems[0].json.keywords : [];
const weekSeed = Math.floor(Date.now() / (7 * 24 * 60 * 60 * 1000));

return domainItems.map((domainItem, localIndex) => {
  const site = domainItem.json;
  const providerOffset = (weekSeed + Number(site.global_index || localIndex)) % providerItems.length;
  const provider = providerItems[providerOffset]?.json || {};
  const providerName = provider.provider || provider.name || provider.title || provider.company || 'Unknown VPN Provider';
  const website = normalizeWebsite(provider.website || provider.url || provider.domain || provider.link);

  return {
    json: {
      ...site,
      provider: providerName,
      competitor_name: providerName,
      website,
      competitor_website: website,
      competitor_rotation_index: providerOffset,
      keywords,
      coordinated_primary_keyword: String(providerName).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') + '-alternative',
      keyword_angle: site.assigned_persona
    }
  };
});

function getNodeItems(name) {
