function cleanJsonText(value) {
  if (value && typeof value === 'object') return value;
  return String(value || '')
    .replace(/^\s*```json\s*/i, '')
    .replace(/^\s*```\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

function parseJsonPayload(value) {
  if (value && typeof value === 'object') return value;
  const cleaned = cleanJsonText(value);
  if (!cleaned) return {};
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const objectMatch = cleaned.match(/\{[\s\S]*\}/);
    if (objectMatch) {
      try {
        return JSON.parse(objectMatch[0]);
      } catch (nestedError) {}
    }
    return {};
  }
}

const contextItems = getNodeItems('Loop Over Domain Batches');

return $input.all().map((item, index) => {
  const context = contextItems[index]?.json || {};
  const raw = item.json.output ?? item.json.text ?? item.json.data ?? item.json;
  const specs = parseJsonPayload(raw);

  return {
    json: {
      ...context,
      pricing: specs.pricing || 'Not disclosed on the scraped public page',
      protocols: specs.protocols || 'Not disclosed on the scraped public page',
      server_count: specs.server_count || 'Not disclosed on the scraped public page',
      competitor_specs: specs
    }
  };
});

function getNodeItems(name) {
  try {
    return $(name).all();
  } catch (error) {
    try {
      return $items(name);
    } catch (fallbackError) {
      return [];
    }
  }
}

function cleanJsonText(value) {
  if (value && typeof value === 'object') return value;
  return String(value || '')
    .replace(/^\s*```json\s*/i, '')
    .replace(/^\s*```\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

function parseJsonPayload(value) {
  if (value && typeof value === 'object') return value;
  const cleaned = cleanJsonText(value);
  if (!cleaned) return { posts: [] };
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    const objectMatch = cleaned.match(/\{[\s\S]*\}/);
    if (objectMatch) {
      try {
        return JSON.parse(objectMatch[0]);
      } catch (nestedError) {}
    }
    throw new Error('Dynamic content agent did not return valid JSON: ' + cleaned.slice(0, 500));
  }
}

const contextItems = getNodeItems('Prepare Article Context');

return $input.all().map((item, index) => {
  const context = contextItems[index]?.json || {};
  const payload = parseJsonPayload(item.json.output ?? item.json.text ?? item.json.data ?? item.json);
  const posts = Array.isArray(payload.posts) ? payload.posts : [];

  return {
    json: {
      output: {
        posts: posts.map((post) => ({
          ...post,
          domain: context.domain,
          brand_name_zh: context.brand_name_zh,
          brand_name_en: context.brand_name_en,
          assigned_persona: context.assigned_persona,
          provider: context.provider,
          competitor_name: context.competitor_name,
          website: context.website,
          competitor_website: context.competitor_website,
          pricing: context.pricing,
          protocols: context.protocols,
          server_count: context.server_count,
          keywords: context.keywords || [],
          coordinated_primary_keyword: context.coordinated_primary_keyword,
          batch_index: context.batch_index,
          batch_position: context.batch_position
        }))
      }
    }
  };
});

