function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function contentToHtml(content) {
  const blocks = String(content || '')
    .replace(/\r\n/g, '\n')
    .split(/\n{2,}/)
    .map((block) => block.trim())
    .filter(Boolean);

  return blocks
    .map((block) => '<p>' + escapeHtml(block).replace(/\n/g, '<br>') + '</p>')
    .join('');
}

function excerptFromContent(content) {
  return String(content || '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 180);
}

return $input.all().map((item) => {
  const data = item.json;
  const now = new Date().toISOString();
  const slug = String(data.slug || '').trim();
  const domain = String(data.domain || '').trim();

  if (!domain) throw new Error('Cannot create GitHub file without domain.');
  if (!slug) throw new Error('Cannot create GitHub file without slug.');

  const postPayload = {
    slug,
    title: data.title || '',
    excerpt: data.excerpt || excerptFromContent(data.content),
    publishedAt: data.publishedAt || now,
    updatedAt: now,
    contentHtml: contentToHtml(data.content),
    metadata: {
      domain,
      brand_name_zh: data.brand_name_zh || '',
      brand_name_en: data.brand_name_en || '',
      assigned_persona: data.assigned_persona || '',
      competitor_name: data.provider || data.competitor_name || '',
      competitor_website: data.website || data.competitor_website || '',
      pricing: data.pricing || '',
      protocols: data.protocols || '',
      server_count: data.server_count || '',
      keywords: data.keywords || [],
      batch_index: data.batch_index,
      batch_position: data.batch_position
    }
  };

  return {
    json: {
      ...data,
      githubFilePath: 'sites/' + domain + '/posts/' + slug + '.json',
      githubFileContent: JSON.stringify(postPayload, null, 2),
      githubCommitMessage: 'Add blog post ' + domain + '/' + slug
    }
  };
});

const items = $input.all();

// Jina Reader's unauthenticated limit is 20 requests per minute.
// The workflow processes 10 domains per batch, then waits 60 seconds before
// requesting the next batch, keeping usage comfortably below that ceiling.
await new Promise((resolve) => setTimeout(resolve, 60000));

return items;
